def test_keyboard_interrupt_during_abort_echo(runner, monkeypatch):
    @click.command()
    def cli():
        raise KeyboardInterrupt

    original_echo = click.core.echo
    interrupt = True

    def echo(*args, **kwargs):
        nonlocal interrupt

        if interrupt:
            interrupt = False
            raise KeyboardInterrupt

        return original_echo(*args, **kwargs)

    monkeypatch.setattr(click.core, "echo", echo)
    result = runner.invoke(cli)

    assert result.exit_code == 1
    assert result.output == "Aborted!\n"


